     1→//! Process management (_start, exit, __libc_start_main)
     2→
     3→use crate::environ;
     4→use crate::memory::init_heap;
     5→use crate::syscall::{SYS_EXIT, syscall1};
     6→use crate::thread::init_tls;
     7→
     8→/// Stack end pointer - set during startup, used for stack overflow detection
     9→#[unsafe(no_mangle)]
    10→pub static mut __libc_stack_end: *mut u8 = core::ptr::null_mut();
    11→
    12→/// Exit the process with the given code
    13→pub fn exit(code: i32) -> ! {
    14→    unsafe {
    15→        syscall1(SYS_EXIT, code as u64);
    16→        core::arch::asm!("ud2", options(noreturn));
    17→    }
    18→}
    19→
    20→/// C-compatible abort
    21→#[unsafe(no_mangle)]
    22→pub extern "C" fn abort() -> ! {
    23→    exit(134) // 128 + SIGABRT(6)
    24→}
    25→
    26→/// Rust panic entry point for panic=abort
    27→/// This is what std's panic machinery calls when panic=abort is set
    28→#[unsafe(no_mangle)]
    29→pub extern "Rust" fn __rust_start_panic(_payload: *mut u8) -> ! {
    30→    abort()
    31→}
    32→
    33→// External reference to the C ABI main that rustc generates
    34→unsafe extern "C" {
    35→    fn main(argc: i32, argv: *const *const u8, envp: *const *const u8) -> i32;
    36→}
    37→
    38→/// The libc entry point called by _start.
    39→///
    40→/// # Safety
    41→/// All pointer arguments must be valid as passed by the kernel/dynamic linker.
    42→#[unsafe(no_mangle)]
    43→pub unsafe extern "C" fn __libc_start_main(
    44→    main_fn: extern "C" fn(i32, *const *const u8, *const *const u8) -> i32,
    45→    argc: i32,
    46→    argv: *const *const u8,
    47→    init: Option<unsafe extern "C" fn(i32, *const *const u8, *const *const u8)>,
    48→    fini: Option<unsafe extern "C" fn()>,
    49→    rtld_fini: Option<unsafe extern "C" fn()>,
    50→    stack_end: *mut u8,
    51→) -> ! {
    52→    // Store stack_end for stack overflow detection
    53→    unsafe {
    54→        __libc_stack_end = stack_end;
    55→    }
    56→
    57→    // Initialize heap first (TLS needs malloc)
    58→    init_heap();
    59→
    60→    // Initialize TLS before calling main
    61→    init_tls();
    62→
    63→    // Calculate envp (follows argv + NULL terminator)
    64→    let envp = unsafe { argv.offset(argc as isize + 1) };
    65→
    66→    // Initialize environ for std::env
    67→    environ::init(envp.cast());
    68→
    69→    // Call init if provided (runs .init_array constructors)
    70→    if let Some(init_fn) = init {
    71→        unsafe {
    72→            init_fn(argc, argv, envp);
    73→        }
    74→    }
    75→
    76→    // Call main and exit with its return value
    77→    let ret = main_fn(argc, argv, envp);
    78→
    79→    // Call fini if provided (runs .fini_array destructors)
    80→    if let Some(fini_fn) = fini {
    81→        unsafe {
    82→            fini_fn();
    83→        }
    84→    }
    85→
    86→    // Call rtld_fini if provided (dynamic linker cleanup)
    87→    if let Some(rtld_fini_fn) = rtld_fini {
    88→        unsafe {
    89→            rtld_fini_fn();
    90→        }
    91→    }
    92→
    93→    exit(ret)
    94→}
    95→
    96→/// Program entry point - called by the kernel
    97→#[unsafe(no_mangle)]
    98→#[unsafe(naked)]
    99→pub extern "C" fn _start() -> ! {
   100→    // Kernel enters with RSP pointing to argc on the stack
   101→    // Stack layout: [argc] [argv[0]] [argv[1]] ... [NULL] [envp[0]] ...
   102→    //
   103→    // We need to call __libc_start_main(main, argc, argv, init, fini, rtld_fini, stack_end)
   104→    core::arch::naked_asm!(
   105→        "xor rbp, rbp",              // Clear frame pointer (ABI requirement)
   106→        "lea rdi, [{main}]",         // arg1: main function address
   107→        "mov rsi, [rsp]",            // arg2: argc
   108→        "lea rdx, [rsp + 8]",        // arg3: argv
   109→        "xor rcx, rcx",              // arg4: init (NULL)
   110→        "xor r8, r8",                // arg5: fini (NULL)
   111→        "xor r9, r9",                // arg6: rtld_fini (NULL)
   112→        "push rsp",                  // arg7: stack_end (on stack)
   113→        "and rsp, -16",              // Align stack to 16 bytes
   114→        "call __libc_start_main",
   115→        "ud2",                       // Should never return
   116→        main = sym main,
   117→    );
   118→}
