     3→use crate::syscall::{SYS_BRK, syscall1};
     4→
     5→// Heap state
     6→static mut HEAP_START: *mut u8 = core::ptr::null_mut();
     7→static mut HEAP_END: *mut u8 = core::ptr::null_mut();
     8→static mut HEAP_CURRENT: *mut u8 = core::ptr::null_mut();
     9→
    10→fn brk(addr: *mut u8) -> *mut u8 {
    11→    unsafe { syscall1(SYS_BRK, addr as u64) as *mut u8 }
    12→}
    13→
    14→pub fn init_heap() {
    15→    unsafe {
    16→        HEAP_START = brk(core::ptr::null_mut());
    17→        HEAP_END = HEAP_START;
    18→        HEAP_CURRENT = HEAP_START;
    19→    }
    20→}
    21→
    22→#[unsafe(no_mangle)]
    23→pub extern "C" fn malloc(size: usize) -> *mut u8 {
    24→    unsafe {
    25→        let aligned_size = (size + 15) & !15;
    26→        let new_current = HEAP_CURRENT.add(aligned_size);
    27→
    28→        if new_current > HEAP_END {
    29→            let grow_size = (aligned_size + 4095) & !4095;
    30→            let new_end = brk(HEAP_END.add(grow_size));
